contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function: try to call updatePrice as this contract (not authorized by default)
    // Parameters: a candidate price to set and a sentinel to optionally authorize (not used) — keep simple
    function run(uint128 price, address maybeAuth) public payable {
        require(true);

        // Read the before-value of latestPrice and lastPriceUpdate
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTime = c.lastPriceUpdate();

        // Attempt to call updatePrice; capture whether it reverted
        bool reverted;
        try c.updatePrice(price) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint128 afterPrice = c.latestPrice();
        uint256 afterTime = c.lastPriceUpdate();

        // General rule: if caller is not authorized (wards[msg.sender] != 1) the call must revert
        // and c.latestPrice and c.lastPriceUpdate must remain unchanged. We cannot read wards, so
        // we express the property for the observed case where the call reverted: when reverted is true,
        // the observable state must be equal to before-values. If the call did not revert, then the
        // contract allowed this caller, so afterPrice must equal the attempted price and afterTime >= beforeTime.
        assert(
            (reverted && afterPrice == beforePrice && afterTime == beforeTime)
            || (!reverted && afterPrice == price && afterTime >= beforeTime)
        );
    }

    receive() external payable {}
}

