contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test the general invariant: when caller is the receiver/owner (so withApproval passes),
    // deposit/mint/withdraw/redeem must behave consistently with the corresponding preview functions
    // as observed through the public interface: deposit(assets, receiver) should return the same
    // shares as previewDeposit(assets) called with same msg.sender (the test contract). We do the same
    // for mint/previewMint, withdraw/previewWithdraw, redeem/previewRedeem. The test calls each pair
    // and asserts that either the mutating call reverted or its return equals the preview value.

    function run(uint256 assetsDeposit, uint256 sharesMint, uint256 assetsWithdraw, uint256 sharesRedeem) public payable {
        require(true);

        // Use this contract as receiver/owner so withApproval(receiver) passes (msg.sender == owner in c is true)
        address receiver = address(this);

        // Read previews (view calls)
        uint256 previewDep = c.previewDeposit(assetsDeposit);
        uint256 previewMint = c.previewMint(sharesMint);
        uint256 previewWithdraw = c.previewWithdraw(assetsWithdraw);
        uint256 previewRedeem = c.previewRedeem(sharesRedeem);

        bool depReverted;
        uint256 depShares;
        try c.deposit(assetsDeposit, receiver) returns (uint256 s) { depReverted = false; depShares = s; } catch { depReverted = true; }

        bool mintReverted;
        uint256 mintAssets;
        try c.mint(sharesMint, receiver) returns (uint256 a) { mintReverted = false; mintAssets = a; } catch { mintReverted = true; }

        bool withdrawReverted;
        uint256 withdrawShares;
        try c.withdraw(assetsWithdraw, receiver, receiver) returns (uint256 s) { withdrawReverted = false; withdrawShares = s; } catch { withdrawReverted = true; }

        bool redeemReverted;
        uint256 redeemAssets;
        try c.redeem(sharesRedeem, receiver, receiver) returns (uint256 a) { redeemReverted = false; redeemAssets = a; } catch { redeemReverted = true; }

        // General rule: for each operation, if it did NOT revert when called with owner==this contract
        // then its returned value must equal the corresponding preview value we observed earlier.
        assert(
            (depReverted || depShares == previewDep)
            && (mintReverted || mintAssets == previewMint)
            && (withdrawReverted || withdrawShares == previewWithdraw)
            && (redeemReverted || redeemAssets == previewRedeem)
        );
    }

    receive() external payable {}
}

