contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test: try deposit and check relation between deposit return and previewDeposit/convertToAssets
    function run(uint256 assets, address receiver) public payable {
        require(receiver != address(0));

        // Call previewDeposit first to observe expected shares for msg.sender (the test contract)
        uint256 previewShares = c.previewDeposit(assets);

        // Try to perform deposit as the receiver must approve via withApproval modifier (msg.sender must equal receiver)
        // The test contract is msg.sender when calling c.deposit, so require receiver == address(this) to satisfy withApproval
        // But we cannot change who deploys this test; require that receiver == address(this) so call proceeds.
        // If receiver != address(this) the call will revert; capture that.
        bool reverted;
        uint256 returnedShares = 0;
        if (receiver == address(this)) {
            try c.deposit{value: 0}(assets, receiver) returns (uint256 shares) {
                reverted = false;
                returnedShares = shares;
            } catch {
                reverted = true;
            }
        } else {
            // calling with non-matching receiver will revert due to withApproval — simulate that behavior by attempting call
            try c.deposit{value: 0}(assets, receiver) returns (uint256 shares) {
                reverted = false;
                returnedShares = shares;
            } catch {
                reverted = true;
            }
        }

        // Read convertToAssets for the shares we got (if any) and for previewShares
        uint256 assetsFromReturned = 0;
        if (!reverted) {
            assetsFromReturned = c.convertToAssets(returnedShares);
        }
        uint256 assetsFromPreviewShares = c.convertToAssets(previewShares);

        // GENERAL ASSERTION:
        // If deposit succeeded then returnedShares must equal previewShares (deposit should follow preview for same caller),
        // and convertToAssets(returnedShares) must equal convertToAssets(previewShares).
        // If deposit reverted then previewShares is some view value and no returnedShares observed.
        assert(reverted || (returnedShares == previewShares && assetsFromReturned == assetsFromPreviewShares));
    }

    receive() external payable {}
}

