contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    // params: assets to deposit, receiver address (must be this contract or another), and a flag whether to call approving wrapper
    function run(uint256 assets, address receiver) public payable {
        // receiver must be a non-zero address and not equal to address(0)
        require(receiver != address(0));

        // We will call deposit(assets, receiver) from this contract (msg.sender == InvMutTest).
        // The liquidity pool's withApproval modifier requires msg.sender == receiver. So deposit should
        // revert unless receiver == address(this). We test that behaviour: if receiver != address(this) then deposit must revert; otherwise it must not revert and its returned shares must equal the view convertToShares(assets).

        bool reverted;
        uint256 returnedShares = type(uint256).max;
        // perform call and capture revert status
        try c.deposit(assets, receiver) returns (uint256 s) {
            reverted = false;
            returnedShares = s;
        } catch {
            reverted = true;
        }

        // Observe convertToShares view for the same assets
        uint256 viewShares = c.convertToShares(assets);

        // General rule asserted below:
        // - If receiver != address(this) then deposit must revert (due to withApproval). If receiver == address(this) then deposit must not revert and returned shares must equal view convertToShares(assets).
        assert((receiver != address(this) && reverted) || (receiver == address(this) && !reverted && returnedShares == viewShares));
    }

    receive() external payable {}
}

