        uint256 maxDep = c.maxDeposit(receiver);
        bool safeOnSuccess = (!reverted) ? (assetsFromReturnedShares >= assets) : true;
        bool expectedRevertReason = reverted ? (maxDep < assets || c.convertToAssets(previewShares) < assets) : true;

        assert(safeOnSuccess && expectedRevertReason);
