    constructor(C _c) { c = _c; deployer = msg.sender; }

    // single public test function driving c
    function run(address caller, uint128 price) public payable {
        require(true);

        // Setup: ensure this contract is authorized (wards[this]==1) by using the constructor authorization
        // The deployed C constructor has set wards[msg.sender]=1 for its deployer; in the checker
        // the InvMutTest contract deploys C, so InvMutTest is authorized. But to test both branches
        // we will perform the call via an external call simulation: if caller == address(this) we'll call directly,
        // otherwise attempt a call that should revert due to auth modifier.

        // Read before values
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTs = c.lastPriceUpdate();

        bool reverted;
        // If caller equals this contract, call should succeed and update storage.
        if (caller == address(this)) {
            reverted = false;
            // perform the state-changing call: authorized path
            c.updatePrice(price);
        } else {
            // attempt to call updatePrice from another address by using transfer trick: call through c with encoded calldata
            // Since msg.sender will be this contract for any external low-level call, we cannot change msg.sender here.
            // So to exercise the revert path, we call through a low-level call on the c contract expecting revert because only wards[msg.sender]==1 allowed.
            // But because msg.sender remains this contract, and this contract is likely authorized, we need to simulate an unauthorized call
            // by first revoking our authorization if possible. The Auth contract exposes deny(address) protected by auth; since we are authorized,
            // we can call deny(address(this)) to revoke ourselves, then try updatePrice which should revert, and finally re-rely to restore state.
            // Revoke authorization
            c.deny(address(this));
            // Now calling updatePrice should revert
            try c.updatePrice(price) {
                reverted = false;
            } catch {
                reverted = true;
            }
            // restore authorization so further interactions by other tests are unaffected
            // note: calling rely requires auth, but we were revoked; however the contract still has at least one ward (the original deployer),
            // and deployer is not available here, so we cannot re-rely; but per constraints the checker deploys fresh c per run so leaving revoked is fine.
        }

        // Read after values
        uint128 afterPrice = c.latestPrice();
        uint256 afterTs = c.lastPriceUpdate();

        // General rule: if the call did not revert then latestPrice equals price and lastPriceUpdate >= beforeTs; if it reverted then storage unchanged
        assert(
            (!reverted && afterPrice == price && afterTs >= beforeTs) ||
            (reverted && afterPrice == beforePrice && afterTs == beforeTs)
        );
    }

    receive() external payable { }
}

