contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry performing the property check
    function run(uint128 price, address caller) public payable {
        require(price > 0 || price == 0, true); // no-op to keep parameter used

        // Ensure caller is authorized (rely) or not depending on input: the test will try both paths
        // We (InvMutTest) are the deployer and initially authorized in C's constructor, but the checker
        // deploys C and then deploys this test passing that C, so msg.sender of c.rely/deny will be this contract.

        // Read before values
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTime = c.lastPriceUpdate();

        // If caller equals address(this) then we will call updatePrice directly (authorized by default from constructor)
        // Otherwise, try to make the specified caller authorized by calling rely(caller) from this contract if this contract is authorized.
        // We perform state changes as top-level calls only.

        // Make caller authorized if possible
        // This contract is authorized (wards[msg.sender] set in C constructor to the deployer of C, which is this test's deployer).
        // However the checker deploys C then deploys this test passing C; wards[msg.sender] == 1 for the deployer of C, not for this contract.
        // To avoid assumptions about deployer relationships, we attempt to rely(caller) and ignore reverts.
        bool relySucceeded;
        try c.rely(caller) {
            relySucceeded = true;
        } catch {
            relySucceeded = false;
        }

        // Now attempt the updatePrice call as the target caller by invoking it through C directly.
        // If caller == address(this) we call c.updatePrice; else we attempt a low-level call to make msg.sender appear as 'caller'
        // We cannot change msg.sender in Solidity, so for the property we observe two situations:
        // - If this contract is authorized and calls updatePrice, it must set latestPrice and lastPriceUpdate.
        // - If msg.sender is not authorized the call must revert.

        bool reverted;
        if (caller == address(this)) {
            // direct call from this contract
            try c.updatePrice(price) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // We cannot make a call originate from an arbitrary external address in this environment.
            // So we simulate the expected behavior: if we successfully made caller authorized via relySucceeded,
            // the only way for caller to call is external to this test; since we cannot perform that, we instead
            // assert the invariant only for the case when this contract calls updatePrice (caller == address(this)).
            // To make the assert still general, we will read post-state and relate changes to whether this contract called.
            // Do nothing here; mark reverted = true to indicate no change by this contract.
            reverted = true;
        }

        uint128 afterPrice = c.latestPrice();
        uint256 afterTime = c.lastPriceUpdate();

        // General rule: If this contract successfully called updatePrice (i.e., caller == address(this) and not reverted),
        // then latestPrice equals the provided price and lastPriceUpdate >= beforeTime.
        // Otherwise, neither latestPrice nor lastPriceUpdate should have changed due to our attempt.
        assert(
            (
                (caller == address(this) && reverted == false) ? (afterPrice == price && afterTime >= beforeTime) : (afterPrice == beforePrice && afterTime == beforeTime)
            )
        );
    }

    receive() external payable {}
}

