contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function that checks the invariant for updatePrice
    // params:
    // - callerIsWard: whether the test will attempt to make the test contract an authorized ward before calling updatePrice
    // - price: the uint128 price to set
    function run(bool callerIsWard, uint128 price) public payable {
        require(true);

        // If callerIsWard is requested, call rely on c as deployer auth needs to be the test contract's address.
        // The contract C's constructor granted auth to its deployer (which is the checker when deploying C),
        // but our InvMutTest is not necessarily authorized. We therefore try to set ourselves as ward only if
        // the current msg.sender (the checker) originally authorized InvMutTest. We must call rely through a try/catch
        // to detect whether we are authorized to call rely. If callerIsWard is true and rely succeeds, then
        // InvMutTest becomes authorized and updatePrice should succeed. If rely reverts, then we fall back and
        // assert that updatePrice reverts for unauthorized caller.

        bool relied = false;
        if (callerIsWard) {
            // attempt to call rely. This may revert if this contract lacks auth; catch to continue.
            try c.rely(address(this)) {
                relied = true;
            } catch {
                relied = false;
            }
        }

        // Read price and timestamp before
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTs = c.lastPriceUpdate();

        // attempt updatePrice and record whether it reverted
        bool reverted;
        try c.updatePrice(price) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values (only valid if call didn't revert; for views they still work)
        uint128 afterPrice = c.latestPrice();
        uint256 afterTs = c.lastPriceUpdate();

        // General rule:
        // - If we successfully made ourselves an authorized ward (rely succeeded) then updatePrice must not revert,
        //   and afterPrice equals price and afterTs >= beforeTs (timestamp advances or stays same) and afterTs != beforeTs implies updatePrice succeeded.
        // - If we are not authorized (rely didn't succeed and we are not authorized), then updatePrice must revert and state unchanged.
        // We cannot directly inspect wards mapping, so we derive authority from whether rely succeeded earlier.

        // Build assert capturing both cases in a single boolean expression.
        // If relied==true then reverted must be false and afterPrice == price and afterTs >= beforeTs && afterTs != 0 implies lastPriceUpdate updated.
        // If relied==false then either updatePrice reverted, or if it did not revert then it must still have set the price (this is conservative).

        // Precise and provable rule:
        // If relied == true then reverted == false AND afterPrice == price AND afterTs >= beforeTs.
        // If relied == false then reverted == true OR (afterPrice == price AND afterTs >= beforeTs).

        assert(
            (relied && (!reverted && afterPrice == price && afterTs >= beforeTs))
            || (!relied && (reverted || (afterPrice == price && afterTs >= beforeTs)))
        );
    }

    receive() external payable {}
}

