    // assets: amount to deposit
    // receiver: the address that should be treated as receiver/owner in withApproval modifier
    function run(uint256 assets, address receiver) public payable {
        require(receiver != address(0));

        // We will call c.deposit as this contract (msg.sender for c calls is this contract).
        // deposit has the modifier withApproval(receiver) which requires msg.sender == receiver.
        // So if receiver == address(this) the call should succeed (assuming investmentManager doesn't revert),
        // otherwise it should revert due to withApproval.

        // Read some view values before the call
        uint256 beforeTotalAssets = c.totalAssets();

        bool reverted;
        uint256 returnedShares = type(uint256).max;

        // Attempt the state-changing call exactly as a top-level statement
        try c.deposit(assets, receiver) returns (uint256 shares) {
            reverted = false;
            returnedShares = shares;
        } catch {
            reverted = true;
        }

        // Read after-values (views are allowed)
        uint256 afterTotalAssets = c.totalAssets();

        // General rule expressed as a single assert:
        // - If this contract is the designated receiver (receiver == address(this)) then deposit must NOT revert
        //   (withApproval allows it) and the returned shares must equal the value reported by convertToShares(assets)
        //   via the public convertToShares view (investmentManager determines conversion). Also totalAssets should be >= beforeTotalAssets.
        // - If receiver != address(this) then deposit must revert due to withApproval (so reverted == true).

        // Note: we cannot inspect investmentManager side effects other than public views. We use convertToShares as the expected conversion.

        uint256 expectedShares = c.convertToShares(assets);

        assert(
            (receiver == address(this) && !reverted && returnedShares == expectedShares && afterTotalAssets >= beforeTotalAssets)
            || (receiver != address(this) && reverted)
        );
    }

    receive() external payable {}
