    // We provide a user address to grant authorization (ward) by calling rely via c (constructor made deployer a ward,
    // which is this contract). To exercise both authorized and unauthorized branches we accept a boolean `authorize`.
    function run(uint128 price, bool authorize, address targetUser) public payable {
