            // revoke permission (safe even if not previously set)
            // only authorized caller (this) can call deny; this contract is authorized by construction
            c.deny(targetUser);
        }

        // read values before making the external updatePrice call
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTime = c.lastPriceUpdate();

