        // but we can assert the following general property about this contract's ability:
        // If this contract (an authorized ward) calls updatePrice, latestPrice becomes price and lastPriceUpdate increases to nonzero.

        // do the actual state-changing call: this contract is authorized initial ward
        bool reverted;
        try c.updatePrice(price) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint128 afterPrice = c.latestPrice();
        uint256 afterTime = c.lastPriceUpdate();

        // General rule: when an authorized caller (this contract) calls updatePrice, it must not revert and must set latestPrice to price
        // and lastPriceUpdate to a strictly greater value than before (and nonzero). If the call reverted, then it must be that this
        // contract was not authorized — but constructor granted it authorization, so call should not revert. We express the rule
        // as: reverted == false AND afterPrice == price AND afterTime > beforeTime AND afterTime != 0
        assert(reverted == false && afterPrice == price && afterTime > beforeTime && afterTime != 0);
    }

    receive() external payable {}
}

