    // and observing whether it reverts or updates the public getters latestPrice() and lastPriceUpdate().
    function run(address authorizer, uint128 price) public payable {
        require(true);

        // Initially read the prior values
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTs = c.lastPriceUpdate();

        // Try to make this contract authorized by calling rely on c via the provided authorizer.
        // The only way to set wards is via rely() which requires auth; authorizer must be an authorized ward already.
        // We attempt the call and ignore failure: two possible worlds — this contract remains unauthorized, or becomes authorized.
        bool becameAuthorized = false;
        // Try to have the external account `authorizer` call c.rely(address(this)) by asking c to call it is impossible from here; instead we attempt two flows:
        // 1) If authorizer==address(this) and this contract is already ward (unlikely), the call would succeed. But we cannot impersonate other EOAs.
        // Therefore we model: either calling updatePrice reverts (unauthorized) or succeeds (authorized). We capture that.

        bool didRevert;
        try c.updatePrice(price) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        uint128 afterPrice = c.latestPrice();
        uint256 afterTs = c.lastPriceUpdate();

        // General rule assertion:
        // If the call reverted, contract state must be unchanged for latestPrice and lastPriceUpdate.
        // If the call succeeded, latestPrice must equal the provided price and lastPriceUpdate must be >= beforeTs and equal to current block timestamp (we cannot read block.timestamp directly in assert),
        // but we can assert monotonicity (afterTs >= beforeTs) and that price was written.
        // This gives a universally quantified invariant distinguishing revert vs success.
        assert(didRevert ? (afterPrice == beforePrice && afterTs == beforeTs) : (afterPrice == price && afterTs >= beforeTs));
    }

    receive() external payable {}
}

