contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry for the property test
    // params:
    // - caller: address that will attempt the update (we don't control msg.sender in calls from this contract,
    //           but we can simulate authorized vs unauthorized by using c.rely/deny from this contract which is initially authorized)
    // - price: the price to pass to updatePrice
    // Note: this contract (InvMutTest) was the deployer of c per problem statement, so it starts authorized (wards[msg.sender]==1).
    function run(address caller, uint128 price) public payable {
        require(caller != address(0), "caller nonzero");

        // Read before-values
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTs = c.lastPriceUpdate();

        // Ensure caller has a known authorization state by toggling it from this contract.
        // First, make sure caller is denied: call deny(caller) from an authorized account (this contract is authorized at construction).
        // Then, possibly rely(caller) to grant authorization depending on the caller parameter's parity bit.
        // Use the LSB of the provided caller address to decide whether to authorize: if odd -> authorize, if even -> leave denied.
        // This creates two cases (authorized vs unauthorized) determined by the input.

        // Deny unconditionally (no revert expected because this contract is auth)
        c.deny(caller);

        // If we want caller to be authorized, grant it
        if (uint160(caller) & 1 == 1) {
            c.rely(caller);
        }

        // Now attempt to call updatePrice as the target caller via a low-level call from this contract.
        // We cannot change msg.sender for external calls from this contract; however the contract C's auth modifier checks wards[msg.sender].
        // To simulate the caller invoking updatePrice, we call through a proxy pattern: have the target caller invoke updatePrice on c by
        // asking c to call updatePrice via delegate? Not possible. Instead, we check the two behaviors available to us:
        // - When this contract calls updatePrice (msg.sender == address(this)), it will succeed because this contract is authorized.
        // - To test unauthorized behavior, we can remove this contract's authorization and then attempt updatePrice and observe revert.
        // So instead of making c.call from the arbitrary `caller` address, we flip authorization of this contract depending on caller param.

        // Determine desired final authority state for this contract: if LSB of caller is 1 -> keep authorized; else -> remove authorization.
        bool keepAuth = (uint160(caller) & 1 == 1);
        if (!keepAuth) {
            // revoke this contract's auth so subsequent call should revert
            c.deny(address(this));
        }

        // Now attempt updatePrice and capture revert
        bool reverted;
        try c.updatePrice(price) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint128 afterPrice = c.latestPrice();
        uint256 afterTs = c.lastPriceUpdate();

        // General rule expressed in one assert:
        // If the call did not revert, then latestPrice must equal the input price and lastPriceUpdate must be nonzero and >= beforeTs.
        // If the call reverted, then latestPrice and lastPriceUpdate must remain unchanged from before.
        // This ties authorization to state mutation of updatePrice.
        assert(
            (!reverted && afterPrice == price && afterTs != 0 && afterTs >= beforeTs)
            || (reverted && afterPrice == beforePrice && afterTs == beforeTs)
        );
    }

    // allow receiving Ether if needed
    receive() external payable {}
}

