    constructor(C _c) { c = _c; }

    // Single public test function. msg.sender for calls on c will be this contract.
    function run(uint128 price) public payable {
        // No precondition needed
        // Read before-values
        uint128 beforePrice = c.latestPrice();
        uint256 beforeLast = c.lastPriceUpdate();

        // Attempt the state-changing call at top-level. Must be its own statement.
        bool reverted;
        try c.updatePrice(price) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint128 afterPrice = c.latestPrice();
        uint256 afterLast = c.lastPriceUpdate();

        // Either reverted and values unchanged, or succeeded and price set and lastPriceUpdate nonzero and not decreased
        assert(
            (reverted && afterPrice == beforePrice && afterLast == beforeLast)
            || (
                !reverted
                && afterPrice == price
                && afterLast != 0
                && afterLast >= beforeLast
            )
        );
    }

    receive() external payable {}
}

