contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: callerAddress is an address we will try to authorize (or not), price is the new price value
    function run(address actor, uint128 price) public payable {
        require(actor != address(0));

        // Initially, msg.sender (this contract) is authorized because C's constructor called in the harness set deployer as ward.
        // But in the checker environment the deployer is the InvMutTest constructor caller; to ensure we can test both
        // authorized and unauthorized cases, we will: if actor == address(this) try updatePrice directly (authorized),
        // otherwise attempt to rely(actor) first from an authorized account (this), then have actor try updatePrice.

        // Record before-values
        uint128 beforePrice = c.latestPrice();
        uint256 beforeLast = c.lastPriceUpdate();

        // If actor != address(this), grant authorization to actor by calling rely on c from this contract (this is authorized)
        // The constructor of C emitted rely for its deployer; in the checker environment that deployer is the test deployer, not this contract.
        // However C has auth modifier that requires wards[msg.sender]==1. We cannot assume this contract is authorized to call rely.
        // Therefore we attempt two scenarios: when actor == address(this) we call updatePrice directly; otherwise we expect updatePrice to revert.

        bool reverted;
        if (actor == address(this)) {
            // call as authorized caller
            try c.updatePrice(price) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // Simulate actor calling updatePrice by invoking c.updatePrice via low-level call with abi-encoded selector and actor as msg.sender is impossible here.
            // The checker executes run once with msg.sender being the test runner, so only this contract can call c; thus other addresses cannot become msg.sender.
            // Hence an updatePrice call from this contract on behalf of a different actor should be unauthorized and revert (since this contract is likely not authorized).
            try c.updatePrice(price) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read after-values
        uint128 afterPrice = c.latestPrice();
        uint256 afterLast = c.lastPriceUpdate();

        // General rule expressed as a single assert:
        // If the call did not revert then latestPrice must equal the provided price and lastPriceUpdate must be >= beforeLast
        // and lastPriceUpdate must equal block.timestamp at the time of the call. We cannot read the internal timestamp at call-time,
        // but block.timestamp for this transaction is accessible through a view: compare that afterLast >= beforeLast and afterLast <= block.timestamp.
        // Combine into one assertion covering both revert and success cases: either the call reverted, or the observed state updates match the price
        // and lastPriceUpdate did not decrease and is no greater than current block.timestamp.

        assert(reverted || (afterPrice == price && afterLast >= beforeLast && afterLast <= block.timestamp));
    }

    receive() external payable { }
}

