    C c;
    constructor(C _c) { c = _c; }

    // single public entry used by the checker
    function run(address caller, uint128 price) public payable {
        // precondition: caller must be a valid non-zero address for the test to be meaningful
        require(caller != address(0));

        // Snapshot values before the attempted update
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTs = c.lastPriceUpdate();

        // We attempt to invoke updatePrice via c by calling it directly from this contract.
        // Only authorized addresses (wards==1) may call updatePrice. The InvMutTest contract
        // is not authorized by default unless c's constructor granted it. We simulate two cases:
        // - if this contract is authorized, the call should succeed and update state accordingly
        // - if not authorized, the call should revert

        bool reverted;
        try c.updatePrice(price) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint128 afterPrice = c.latestPrice();
        uint256 afterTs = c.lastPriceUpdate();

        // General rule:
        // If the call reverted then the public state must be unchanged (latestPrice and lastPriceUpdate equal to before values).
        // If the call did not revert then latestPrice must equal the provided price and lastPriceUpdate must be >= beforeTs.
        assert(
            (reverted && afterPrice == beforePrice && afterTs == beforeTs) ||
            (!reverted && afterPrice == price && afterTs >= beforeTs)
        );
    }

    receive() external payable {}
}

