contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test entry exercising updatePrice and its observable effects
    function run(uint128 price, address caller) public payable {
        // must have enough balance if we ever forward Ether (we don't here)
        require(true);

        // read before values
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTs = c.lastPriceUpdate();

        // attempt to call updatePrice as this contract (msg.sender will be this test contract
        // when calling c.updatePrice). The provided `caller` parameter is only used to decide
        // whether we first attempt to grant auth by calling rely; we can only call rely if
        // this contract is already authorised. Since the test contract is NOT the original
        // deployer of c in the general checker, we cannot assume it has auth. So we first
        // try to call rely via a try/catch to detect whether rely succeeds. If rely reverts,
        // we mark that and proceed to call updatePrice which should then revert as well.

        bool relied = false;
        bool updateReverted = false;

        // try to call rely(caller) on c to attempt to set auth for this contract
        // Note: rely expects msg.sender to be authorised, so this will usually revert.
        try c.rely(address(this)) {
            relied = true;
        } catch {
            relied = false;
        }

        // Now attempt updatePrice and record if it reverted
        try c.updatePrice(price) {
            updateReverted = false;
        } catch {
            updateReverted = true;
        }

        // read after values
        uint128 afterPrice = c.latestPrice();
        uint256 afterTs = c.lastPriceUpdate();

        // General rule to assert:
        // If updatePrice did not revert then latestPrice must equal the provided price
        // and lastPriceUpdate must be >= beforeTs (timestamp monotonicity) and > beforeTs when price changed.
        // If updatePrice reverted then contract state must be unchanged regarding latestPrice and lastPriceUpdate.
        assert(
            // successful update: observable values reflect the update
            (!updateReverted && afterPrice == price && afterTs >= beforeTs) ||
            // reverted update: no change to observable values
            (updateReverted && afterPrice == beforePrice && afterTs == beforeTs)
        );
    }

    receive() external payable {}
}

