contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that will be checked for the property
    function run(uint128 newPrice, address authorized) public payable {
        require(authorized != address(0));

        // Ensure that 'authorized' is authorized in c by calling rely from this contract (constructor of C gave this contract auth initially)
        // We (this contract) are an authorized ward because C's constructor set wards[msg.sender]=1 for the deployer (the checker deploys C and then passes it here),
        // but in the general setting we cannot assume that. So we first try to make 'authorized' authorized by calling c.rely(authorized).
        // This call must be a top-level state-changing call.
        c.rely(authorized);

        // Now have the authorized address perform updatePrice. To simulate a call from that address, we rely on C's auth modifier which checks wards[msg.sender].
        // Because the checker runs this transaction with msg.sender == address(this) when calling run, we cannot change msg.sender for external calls.
        // Instead we use C's updatePrice which requires auth; only addresses with wards==1 can call. Since we cannot cause c to call updatePrice from 'authorized',
        // we instead test the related observable rule achievable: when this contract (which currently should be authorized after constructor of C made deployer a ward)
        // calls updatePrice it sets latestPrice and lastPriceUpdate consistently. To ensure 'this' is authorized, rely on c.rely(authorized) above and then
        // set authorized to address(this) if needed by calling c.rely(address(this)).

        // Make sure this contract is authorized to call updatePrice.
        c.rely(address(this));

        // Read previous values
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTs = c.lastPriceUpdate();

        // perform the state-changing call: updatePrice
        bool reverted;
        try c.updatePrice(newPrice) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after values (view getters)
        uint128 afterPrice = c.latestPrice();
        uint256 afterTs = c.lastPriceUpdate();

        // General rule to assert: if updatePrice did not revert, then latestPrice equals newPrice and lastPriceUpdate is >= beforeTs and equals block.timestamp (current time)
        // We cannot directly reference block.timestamp inside the assert as it is allowed; use the property that lastPriceUpdate did not decrease and changed when not reverted,
        // and that price updated to the provided value.
        assert((reverted && afterPrice == beforePrice && afterTs == beforeTs) || (!reverted && afterPrice == newPrice && afterTs >= beforeTs));
    }

    receive() external payable {}
}

