    constructor(C _c) { c = _c; }

    function run(uint128 newPrice) public payable {
        // Snapshot observable before-values
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTs = c.lastPriceUpdate();

        // Attempt the state-changing call updatePrice(newPrice) and record whether it reverted
        bool callReverted;
        try c.updatePrice(newPrice) {
            callReverted = false;
        } catch {
            callReverted = true;
        }

        // Read after-values
        uint128 afterPrice = c.latestPrice();
        uint256 afterTs = c.lastPriceUpdate();

        // Assert: if reverted then no change; if succeeded then latestPrice == newPrice and timestamp not decreased
        assert(
            (callReverted && afterPrice == beforePrice && afterTs == beforeTs)
            || (!callReverted && afterPrice == newPrice && afterTs >= beforeTs)
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with parameters: caller (address) is implicit (this contract),
    // so we provide price and a bool indicating whether we will call via an authorized path.
    // Since this contract is the deployer of C in the environment, its constructor was run there
    // and wards[msg.sender] was set for that deployer; however the checker deploys a fresh C and
    // passes it into our constructor so we cannot assume our address is authorized. To cover both
    // possibilities we first try to call updatePrice and observe if it reverted; if not, we
    // capture the state changes. We then assert the general rule: if the call succeeded then
    // latestPrice equals the given price and lastPriceUpdate equals block.timestamp; if the call
    // reverted then latestPrice and lastPriceUpdate are unchanged.

    function run(uint128 price) public payable {
        // read before-values
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTs = c.lastPriceUpdate();

        bool reverted;
        // perform the state-changing call at top-level
        try c.updatePrice(price) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint128 afterPrice = c.latestPrice();
        uint256 afterTs = c.lastPriceUpdate();

        // General rule:
        // - If the call did not revert then latestPrice == price and lastPriceUpdate == block.timestamp
        // - If the call reverted then both latestPrice and lastPriceUpdate remain equal to before-values
        assert((!reverted && afterPrice == price && afterTs == block.timestamp) || (reverted && afterPrice == beforePrice && afterTs == beforeTs));
    }

    receive() external payable {}
}

