contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry executing the property check
    function run(address caller, uint128 price) public payable {
        require(caller != address(0));
        // Ensure the test contract is an authorized ward so it can call file/rely if needed
        // The constructor of C already set its deployer as ward, but our contract is not that deployer.
        // We test both authorized and unauthorized behavior by trying to set authorization via the contract's public auth functions.

        // First, attempt to call updatePrice as unauthorized: should revert.
        bool revertedUnauthorized;
        try c.updatePrice(price) {
            revertedUnauthorized = false;
        } catch {
            revertedUnauthorized = true;
        }

        // Next, try to make 'caller' authorized by having the contract call rely(caller) if possible.
        // Only an authorized ward can call rely; since we don't know wards, try to call rely and ignore failures.
        // This call is allowed to revert; it will fail harmlessly if msg.sender isn't authorized.
        // But we must not nest a state-changing call inside try per constraints — however top-level try is allowed for external call.
        // Use a top-level call to c.rely(caller) and ignore revert via try/catch to avoid halting the test.
        try c.rely(caller) {
        } catch {}

        // Now perform the updatePrice call with msg.sender being this contract (InvMutTest) — but the contract cannot impersonate 'caller'.
        // To test authorized path, attempt to rely the test contract itself and then call updatePrice.
        // Try to authorize this contract as ward.
        try c.rely(address(this)) {
        } catch {}

        // Record state before attempting authorized update
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTs = c.lastPriceUpdate();

        bool revertedAuthorized;
        try c.updatePrice(price) {
            revertedAuthorized = false;
        } catch {
            revertedAuthorized = true;
        }

        uint128 afterPrice = c.latestPrice();
        uint256 afterTs = c.lastPriceUpdate();

        // The general rule to assert:
        // If the authorized call did NOT revert, then latestPrice must equal the provided price and lastPriceUpdate must be >= beforeTs.
        // If the authorized call reverted, then state must be unchanged from before (price and timestamp equal before-values).
        // Also, the unauthorized initial call must have reverted (ensuring only authorized callers can set price).
        assert(
            revertedUnauthorized &&
            (
                (!revertedAuthorized && afterPrice == price && afterTs >= beforeTs) ||
                (revertedAuthorized && afterPrice == beforePrice && afterTs == beforeTs)
            )
        );
    }

    receive() external payable {}
}

