        try c.rely(tryAuthorize) {
        } catch {
        }

        // Now try to authorize this test contract itself; again may revert but must be top-level.
        try c.rely(address(this)) {
        } catch {
        }

        // Attempt to call updatePrice again and observe whether it reverts
        bool revertedAuthorized;
        try c.updatePrice(price) {
            revertedAuthorized = false;
        } catch {
