contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test attempts mint and burn from this contract before and after trying to become a ward.
    // Parameters: target address to mint/burn to/from and values for mint and burn.
    function run(address target, uint256 mintVal, uint256 burnVal) public payable {
        require(target != address(0));

        // First attempt mint as currently unauthorized (most likely) and record whether it reverted.
        bool mintRevertedBefore;
        try c.mint(target, mintVal) {
            mintRevertedBefore = false;
        } catch {
            mintRevertedBefore = true;
        }

        // First attempt burn as currently unauthorized and record whether it reverted.
        bool burnRevertedBefore;
        try c.burn(target, burnVal) {
            burnRevertedBefore = false;
        } catch {
            burnRevertedBefore = true;
        }

        // Try to become a ward by calling rely(address(this)). This may revert if this contract is not authorized.
        // We ignore its outcome; it must be a top-level statement.
        try c.rely(address(this)) {
        } catch {
        }

        // After attempting to become a ward, attempt mint and burn again and record revert flags.
        bool mintRevertedAfter;
        try c.mint(target, mintVal) {
            mintRevertedAfter = false;
        } catch {
            mintRevertedAfter = true;
        }

        bool burnRevertedAfter;
        try c.burn(target, burnVal) {
            burnRevertedAfter = false;
        } catch {
            burnRevertedAfter = true;
        }

        // General rule asserted:
        // For each of mint and burn: if the call did not revert after attempting to rely then it must also not have reverted before
        // OR if it did revert before then either rely failed (so still not authorized) and it still reverts after, or rely succeeded and it stops reverting.
        // Concretely: it's forbidden that the call was non-reverting before and then reverts after relying (authorization should not be removed by calling rely).
        assert(
            // mint cannot go from non-revert to revert after trying to rely
            !(mintRevertedBefore == false && mintRevertedAfter == true)
            &&
            // burn cannot go from non-revert to revert after trying to rely
            !(burnRevertedBefore == false && burnRevertedAfter == true)
        );
    }

    receive() external payable {}
}

