contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry performing the property test
    function run(uint256 assets, address receiver) public payable {
        require(receiver != address(0));
        // Ensure this contract is the caller for c calls (it is), and record totalAssets before
        uint256 beforeTotalAssets = c.totalAssets();

        bool reverted;
        uint256 returnedShares = 0;
        // Call deposit which requires msg.sender == receiver due to withApproval modifier
        // If receiver != address(this) the call will revert (LiquidityPool/no-approval) unless
        // investmentManager or other behaviour causes different revert. We capture revert.
        try c.deposit{value: 0}(assets, receiver) returns (uint256 shares) {
            reverted = false;
            returnedShares = shares;
        } catch {
            reverted = true;
        }

        uint256 afterTotalAssets = c.totalAssets();

        // General rule (assert): if the deposit call reverted, then totalAssets must be unchanged;
        // if it succeeded, totalAssets may change but then returnedShares must equal convertToShares(assets)
        // as an observable consistency between shares returned and conversion function.
        // We avoid underflow and keep only external views: convertToShares is public.
        assert(
            (reverted && afterTotalAssets == beforeTotalAssets)
            || (!reverted && returnedShares == c.convertToShares(assets))
        );
    }

    receive() external payable {}
}

