contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry performing the property check
    // params: caller (address that will be granted or not granted auth), price to set,
    // and a flag grantAuth indicating whether this contract should rely the caller before calling updatePrice.
    function run(address caller, uint128 price, bool grantAuth) public payable {
        require(caller != address(0) && caller != address(this));

        // First, ensure this test contract is authorized so it can manipulate wards if needed.
        // The contract C's constructor granted msg.sender (the deployer) authorization; here msg.sender is the deployer of C,
        // but the checker deploys a fresh C and then constructs this test with that C, so this contract is *not* necessarily authorized.
        // We attempt to call c.rely to authorize this contract; that call may revert if this contract is not authorized, so we ignore revert.
        // We capture whether we are authorized by trying to call c.updatePrice ourselves with the provided price and checking revert.

        bool thisAuth;
        try c.updatePrice(price) {
            thisAuth = true;
        } catch {
            thisAuth = false;
        }

        // If this test contract is not authorized, we cannot perform ward management; therefore we only proceed to test behavior
        // for caller when this contract is authorized to call c.rely/deny. To still be general, if thisAuth is false we will only assert
        // the property that updatePrice reverts for unauthorized callers (since we cannot set wards). To be able to set wards for caller,
        // require that this contract is authorized when grantAuth==true.
        if (grantAuth) {
            // require we have ability to grant authorization; otherwise the rest can't be arranged
            require(thisAuth, "InvMutTest: cannot grant auth");
            // grant caller authorization
            c.rely(caller);
        } else {
            // if not granting, ensure caller is not authorized by trying to deny (safe even if not authorized — will revert if not)
            if (thisAuth) {
                // if we are authorized we can explicitly deny caller to ensure they are not authorized
                c.deny(caller);
            }
        }

        // Read front-state values before the call
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTimestamp = c.lastPriceUpdate();

        // Now simulate calling updatePrice as `caller`. Because the checker executes run as a single transaction where msg.sender is this contract,
        // we cannot directly set msg.sender to `caller`. Instead, use low-level call to c from this contract but with encoded calldata for updatePrice
        // and specify the from by arranging that the function is executed as if by `caller` cannot be done; however the contract's auth modifier checks wards[msg.sender],
        // so to emulate caller we must set wards[caller] = 1 and then make an external call that causes msg.sender to be `caller` — impossible.
        // Instead we exercise the property by using the public functions rely/deny that accept an address parameter and check msg.sender's auth; 
        // to actually call updatePrice as an address other than this contract is not possible within the constraints. Therefore we instead assert the logical
        // implication: if the caller address is authorized (wards[caller]==1) then calling updatePrice (when invoked by that authorized address) would set latestPrice and timestamp.
        // We can observe that setting authorization for the caller and then having this contract call updatePrice itself (when this contract is authorized) results in the expected state change.

        // So perform the decisive call as this contract (which must be authorized if grantAuth was true or thisAuth true):
        bool didCallRevert;
        try c.updatePrice(price) {
            didCallRevert = false;
        } catch {
            didCallRevert = true;
        }

        uint128 afterPrice = c.latestPrice();
        uint256 afterTimestamp = c.lastPriceUpdate();

        // General rule asserted:
        // - If this call did not revert, then latestPrice must equal the provided price and lastPriceUpdate must be strictly >= beforeTimestamp and > 0.
        // - If the call reverted, then either the caller was unauthorized (we couldn't call updatePrice) or some other failure occurred; in that case we assert that price and timestamp did not change.
        // We express this as a single assert combining both cases.
        assert(
            (!didCallRevert && afterPrice == price && afterTimestamp > 0 && afterTimestamp >= beforeTimestamp)
            || (didCallRevert && afterPrice == beforePrice && afterTimestamp == beforeTimestamp)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry performing the property check
    // Params: price to set, and a flag grantAuth indicating we will attempt to authorize this contract before calling updatePrice
    function run(uint128 price, bool grantAuth) public payable {
        // no special preconditions
        require(true);

        // Try to observe whether this contract is currently authorized by attempting updatePrice.
        bool initialCallReverted;
        try c.updatePrice(price) {
            initialCallReverted = false;
        } catch {
            initialCallReverted = true;
        }

        // If requested and if currently authorized, grant authorization to some other address (no-op for the property) OR ensure we can set wards for this contract
        // To be able to ensure deterministic setup we will, when grantAuth==true and we were already authorized, flip auth off then on for this contract.
        // These state-changing calls must be top-level statements.
        if (grantAuth && !initialCallReverted) {
            c.deny(address(this));
            c.rely(address(this));
        }

        // Read values before decisive call
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTimestamp = c.lastPriceUpdate();

        // Decisive call: attempt to set the price. Must be a top-level statement.
        bool didRevert;
        try c.updatePrice(price) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // Read after-values
        uint128 afterPrice = c.latestPrice();
        uint256 afterTimestamp = c.lastPriceUpdate();

        // General property (single assert):
        // If the call succeeded then latestPrice equals the provided price and lastPriceUpdate is nonzero and not less than beforeTimestamp.
        // If the call reverted then both latestPrice and lastPriceUpdate remain exactly as before.
        assert(
            (!didRevert && afterPrice == price && afterTimestamp > 0 && afterTimestamp >= beforeTimestamp)
            || (didRevert && afterPrice == beforePrice && afterTimestamp == beforeTimestamp)
        );
    }

    receive() external payable {}
}

