    C c;
    constructor(C _c) { c = _c; }

    // Single public entry performing the property check
    // Params: price to set, and a flag flipAuth that when true will try to flip authorization by calling deny then rely on this contract.
    function run(uint128 price, bool flipAuth) public payable {
        require(true);

        // Read before-values (views allowed anywhere)
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTimestamp = c.lastPriceUpdate();

        // Optional setup: flip auth (each is a top-level state-changing call)
        if (flipAuth) {
            c.deny(address(this));
            c.rely(address(this));
        }

        // Decisive call: attempt to set the price, capture whether it reverted
        bool didRevert;
        try c.updatePrice(price) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // Read after-values
        uint128 afterPrice = c.latestPrice();
        uint256 afterTimestamp = c.lastPriceUpdate();

        // Single assert: either the call succeeded and price was set and timestamp is nonzero and not decreased,
        // or it reverted and both observed values are unchanged.
        assert((!didRevert && afterPrice == price && afterTimestamp > 0 && afterTimestamp >= beforeTimestamp)
               || (didRevert && afterPrice == beforePrice && afterTimestamp == beforeTimestamp));
    }

    receive() external payable {}
}

