contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry with inputs: caller (address that will be authorized or not), price to set
    // We cannot change msg.sender when calling c from this contract, so to simulate authorized caller we
    // first make this contract an authorized ward by calling rely in the constructor of C already done,
    // but per constraints we must treat the fresh c as deployed with wards[msg.sender]=1 where msg.sender is deployer
    // The test will check two cases depending on the boolean `makeAuth`: if true, this contract will call c.file to set an investmentManager
    // That requires auth so will only succeed if this contract is already authorized; instead we use try/catch around updatePrice

    function run(uint128 price) public payable {
        require(true);

        // Read before values
        uint128 beforePrice = c.latestPrice();
        uint256 beforeTimestamp = c.lastPriceUpdate();

        // Attempt to call updatePrice; it requires msg.sender to be authorized (wards[msg.sender] == 1).
        bool reverted;
        try c.updatePrice(price) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint128 afterPrice = c.latestPrice();
        uint256 afterTimestamp = c.lastPriceUpdate();

        // General rule:
        // If the call did not revert then latestPrice must equal the provided price and lastPriceUpdate must be >= beforeTimestamp.
        // If the call reverted then the state must be unchanged (both fields equal their before values).
        assert((!reverted && afterPrice == price && afterTimestamp >= beforeTimestamp) || (reverted && afterPrice == beforePrice && afterTimestamp == beforeTimestamp));
    }

    receive() external payable {}
}
